/* @lc app=leetcode id=3388 lang=kotlin */ class Solution { fun beautifulSplits(nums: IntArray): Int = nums.size.let { n -> (0 until n).map { i -> if (i == 0) 0 else generateSequence(0) { it + 1 }.takeWhile { i + it < n && nums[it] == nums[i + it] }.count() }.let { z0 -> (n - 1 downTo 1).fold(IntArray(n + 2) to 0) { (prev, tot), i -> IntArray(n + 2).also { row -> (0 until n).forEach { j -> if (nums[i] == nums[j]) row[j] = prev[j + 1] + 1 } }.let { row -> row to tot + (i + 1 until n).count { j -> (z0[i] >= i && j >= 2 * i) || (2 * j - i <= n && row[j] >= j - i) } } }.second } } }